create function issued_receipt_keeps_what_it_certifies() returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  if exists (select from pg_locks
             where locktype = 'advisory' and pid = pg_backend_pid() and granted
               and classid = 0 and objid = 20261110 and objsubid = 1) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if (new.id, new.donor_id, new.kind, new.donation_id, new.receipt_year, new.number, new.issued_on, new.issued_at, new.locale,
        new.fingerprint, new.schema_version, new.frozen, new.signature_image_sha256, new.portrait_image_sha256, new.signing_key_id,
        new.proof, new.status_sha256, new.supersedes_id)
       is not distinct from
       (old.id, old.donor_id, old.kind, old.donation_id, old.receipt_year, old.number, old.issued_on, old.issued_at, old.locale,
        old.fingerprint, old.schema_version, old.frozen, old.signature_image_sha256, old.portrait_image_sha256, old.signing_key_id,
        old.proof, old.status_sha256, old.supersedes_id)
       and (old.status = 'ACTIVE'
            or (new.status, new.superseded_at, new.withdrawn_at, new.withdrawal_reason)
               is not distinct from (old.status, old.superseded_at, old.withdrawn_at, old.withdrawal_reason)) then
      return new;
    end if;
  end if;
  raise exception 'issued_receipt % refused: an issued receipt keeps what it certifies and leaves ACTIVE at most once', tg_op;
end
$$
